"""audit-ai-service — application service (generated by A2C CodeGenAgent).

The single public entry point `handle()` applies every mandatory NFR:
idempotency per request_id, circuit breaker + retry with backoff around the
domain step, structured logging and tracing, a health probe and graceful
shutdown. Domain logic belongs in `_process()`.
"""
from typing import Any, Dict, Optional

from e2a_base import BaseIdempotencyStore, CircuitBreaker, RetryBudget

from .nfr import HEALTH_PATH, call_with_resilience, install_graceful_shutdown, run_idempotent
from .observability import logger, traced


class AuditAiServiceService:
    """Application service for audit-ai-service."""

    def __init__(self, store: BaseIdempotencyStore,
                 breaker: Optional[CircuitBreaker] = None,
                 budget: Optional[RetryBudget] = None) -> None:
        self._store = store
        self._breaker = breaker or CircuitBreaker(failure_threshold=5, reset_seconds=30.0)
        self._budget = budget or RetryBudget()
        self._accepting = True

    def handle(self, request_id: str, tenant_id: str, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Single public entry point."""
        if not self._accepting:
            raise RuntimeError("service is shutting down")
        with traced("audit-ai-service.handle"):
            return run_idempotent(
                self._store, request_id, tenant_id,
                lambda: call_with_resilience(lambda: self._process(payload),
                                             self._breaker, self._budget))

    def health(self) -> Dict[str, str]:
        return {"path": HEALTH_PATH, "status": "UP" if self._accepting else "DRAINING",
                "circuit": self._breaker.state}

    def enable_graceful_shutdown(self) -> None:
        install_graceful_shutdown(self.shutdown)

    def shutdown(self) -> None:
        self._accepting = False
        logger.info("graceful shutdown: no longer accepting work")

    # ------------------------------------------------------------ domain
    def _process(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Replace with the domain logic of audit-ai-service."""
        return {"accepted": True, "payload": payload}
